head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[audio > P > muted]<br/>Audio 컴포넌트에서 오디오의 볼륨을 음소거 상태로 설정합니다.",
    "validation" : [
        "muted 설정 시, 오디오의 볼륨을 음소거 상태로 설정합니다.",
        "빈 문자열('') 을 설정해도 음소거 상태로 설정합니다.",
        "Audio 컴포넌트는 muted 속성값을 출력 HTML 의 audio 태그에 전달하며, 실제 동작은 브라우저의 HTML5 audio 처리에 따라 결정됩니다.",
        "속성을 한번이라도 설정하면 속성명이 유지되고, 속성명 정의만으로 해당 기능이 설정됩니다.",
        "따라서, 소스에서 직접 속성명을 제거해야 해당 기능이 해제됩니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 재생 중 음소거 상태 확인
scwin.btn_playAndCheck_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");

    [el1, el2, el3].forEach(function (el) {
        el.currentTime = 0;
        el.play();
    });

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("muted 를 muted 로 설정 - 재생 중 음소거 상태(muted) : " + el1.muted + " , 볼륨(volume) : " + el1.volume);
        wf_body_bottom.getObj("scwin").setReturnValue("muted 를 빈 문자열로 설정 - 재생 중 음소거 상태(muted) : " + el2.muted);
        wf_body_bottom.getObj("scwin").setReturnValue("소스에서 muted 속성명 제거 시 해제 - 속성값 : " + JSON.stringify(el3.getAttribute("muted")) + " , 재생 중 음소거 상태(muted) : " + el3.muted);

        [el1, el2, el3].forEach(function (el) { el.pause(); });
    }, 1000);
};



// 출력 HTML audio 태그로 전달된 muted 속성값과 속성명 정의만으로의 설정 상태 확인
scwin.btn_getMutedAttr_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");

    wf_body_bottom.getObj("scwin").setReturnValue("출력 HTML audio 태그의 muted 속성값 - target1 : " + JSON.stringify(el1.getAttribute("muted")) + " , target2 : " + JSON.stringify(el2.getAttribute("muted")) + " , target3 : " + JSON.stringify(el3.getAttribute("muted")));
    wf_body_bottom.getObj("scwin").setReturnValue("속성명 정의만으로 기능 설정 - 속성명만 정의한 target2 의 muted : " + el2.muted + " , 값을 명시한 target1 의 muted : " + el1.muted);
};
